// Content with portions generated by generative AI platform
package org.eclipse.kura.web;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.atLeastOnce;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.io.IOException;
import java.util.Properties;

import javax.servlet.Servlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

import org.eclipse.kura.system.SystemService;
import org.eclipse.kura.web.session.Attributes;
import org.eclipse.kura.web.session.FakeHttpSession;
import org.junit.After;
import org.junit.Test;
import org.osgi.service.http.HttpContext;
import org.osgi.service.http.HttpService;

/**
 * Feature: allocate a session on the Web Console authentication paths only when an authentication flow is actually
 * entered, so that unauthenticated requests cannot allocate unbounded server side state.
 */
public class AuthenticationPathSessionCreationTest {

    private static final String LOGIN_PAGE_PATH = "/admin/auth";
    private static final String PASSWORD_AUTH_PATH = "/admin/login/password";
    private static final String CERT_AUTH_PATH = "/admin/login/cert";
    private static final String EXTENSION_LOGIN_PATH = "/exampleext/dummylogin";
    private static final String SECURED_PATH = "/admin/denali/device";

    // ----------------------------------------------------------------
    //
    // Scenarios
    //
    // ----------------------------------------------------------------

    @Test
    public void noSessionIsCreatedOnRequestToLoginPage() throws IOException {
        givenConsole();
        givenSessionContext();
        givenRequestTo(LOGIN_PAGE_PATH);

        whenSecurityIsHandled();

        thenRequestIsAllowed();
        thenNoSessionIsCreated();
    }

    @Test
    public void noSessionIsCreatedOnRequestToPasswordAuthenticationPath() throws IOException {
        givenConsole();
        givenSessionContext();
        givenRequestTo(PASSWORD_AUTH_PATH);

        whenSecurityIsHandled();

        thenRequestIsAllowed();
        thenNoSessionIsCreated();
    }

    @Test
    public void noSessionIsCreatedOnRequestToCertificateAuthenticationPath() throws IOException {
        givenConsole();
        givenSessionContext();
        givenRequestTo(CERT_AUTH_PATH);

        whenSecurityIsHandled();

        thenRequestIsAllowed();
        thenNoSessionIsCreated();
    }

    @Test
    public void sessionIsCreatedOnRequestToExtensionLoginServletPath() throws Exception {
        givenConsole();
        givenRegisteredLoginServlet(EXTENSION_LOGIN_PATH);
        givenSessionContext();
        givenRequestTo(EXTENSION_LOGIN_PATH);

        whenSecurityIsHandled();

        thenRequestIsAllowed();
        thenSessionIsCreated();
    }

    @Test
    public void requestToExtensionLoginServletPathIsRejectedWhenUnauthenticatedSessionLimitIsReached()
            throws Exception {
        givenConsole();
        givenMaxUnauthenticatedSessionCount(1);
        givenRegisteredLoginServlet(EXTENSION_LOGIN_PATH);
        givenSessionContext();
        givenExhaustedUnauthenticatedSessionLimit(EXTENSION_LOGIN_PATH);
        givenRequestTo(EXTENSION_LOGIN_PATH);

        whenSecurityIsHandled();

        thenRequestIsRejectedWith(HttpServletResponse.SC_SERVICE_UNAVAILABLE);
        thenNoSessionIsCreated();
    }

    @Test
    public void requestToExtensionLoginServletPathIsAllowedWhenReusingAnAlreadyTrackedSession()
            throws Exception {
        givenConsole();
        givenMaxUnauthenticatedSessionCount(1);
        givenRegisteredLoginServlet(EXTENSION_LOGIN_PATH);
        givenSessionContext();
        givenExhaustedUnauthenticatedSessionLimit(EXTENSION_LOGIN_PATH);
        givenRequestReusingTheExistingSession(EXTENSION_LOGIN_PATH);

        whenSecurityIsHandled();

        thenRequestIsAllowed();
    }

    @Test
    public void requestToSecuredPathWithoutSessionIsRejected() throws IOException {
        givenConsole();
        givenSessionContext();
        givenRequestTo(SECURED_PATH);

        whenSecurityIsHandled();

        thenRequestIsRejectedWith(HttpServletResponse.SC_UNAUTHORIZED);
        thenNoSessionIsCreated();
    }

    // ----------------------------------------------------------------
    //
    // Steps
    //
    // ----------------------------------------------------------------

    private Console console;
    private SystemService systemService;
    private HttpContext sessionContext;
    private HttpServletRequest request;
    private HttpServletResponse response;
    private FakeHttpSession session;
    private FakeHttpSession trackedSession;
    private boolean result;

    @After
    public void cleanUp() {
        Console.setInstance(null);
        Console.setConsoleOptions(null);
    }

    private void givenConsole() {
        this.console = new Console();
        Console.setInstance(this.console);
        this.console.setHttpService(mock(HttpService.class));
        Console.setConsoleOptions(ConsoleOptions.defaultConfiguration());

        this.systemService = mock(SystemService.class);
        // not exercising the limit here: the property is left unset so Console falls back to its
        // built-in default, which is large enough to keep the scenarios below focused on
        // routing/session-creation. The limit itself is covered by
        // requestToExtensionLoginServletPathIsRejectedWhenUnauthenticatedSessionLimitIsReached()
        when(this.systemService.getProperties()).thenReturn(new Properties());
        this.console.setSystemService(this.systemService);
    }

    private void givenMaxUnauthenticatedSessionCount(final int maxCount) {
        final Properties properties = new Properties();
        properties.setProperty(Console.MAX_UNAUTHENTICATED_SESSIONS_PROPERTY, Integer.toString(maxCount));
        when(this.systemService.getProperties()).thenReturn(properties);
    }

    private void givenRegisteredLoginServlet(final String path) throws Exception {
        this.console.registerLoginServlet(path, mock(Servlet.class));
    }

    private void givenSessionContext() {
        this.sessionContext = this.console.initSessionContext(mock(HttpContext.class));
    }

    private void givenExhaustedUnauthenticatedSessionLimit(final String path) throws IOException {
        givenRequestTo(path);
        assertTrue("the session context should have accepted the request",
                this.sessionContext.handleSecurity(this.request, this.response));
        this.trackedSession = this.session;
    }

    private void givenRequestReusingTheExistingSession(final String uri) {
        givenRequestTo(uri);

        when(this.request.getSession()).thenReturn(this.trackedSession);
        when(this.request.getSession(true)).thenReturn(this.trackedSession);
        when(this.request.getSession(false)).thenReturn(this.trackedSession);
    }

    private void givenRequestTo(final String uri) {
        this.request = mock(HttpServletRequest.class);
        this.response = mock(HttpServletResponse.class);
        this.session = new FakeHttpSession();

        when(this.request.getRequestURI()).thenReturn(uri);
        when(this.request.getLocalPort()).thenReturn(443);
        when(this.request.getRemoteAddr()).thenReturn("192.168.1.100");
        when(this.request.getSession()).thenReturn(this.session);
        when(this.request.getSession(true)).thenReturn(this.session);
        when(this.request.getSession(false)).thenReturn(null);
    }

    private void whenSecurityIsHandled() throws IOException {
        this.result = this.sessionContext.handleSecurity(this.request, this.response);
    }

    private void thenRequestIsAllowed() {
        assertTrue("the request should have been accepted", this.result);
    }

    private void thenRequestIsRejectedWith(final int expectedStatus) throws IOException {
        assertFalse("the request should have been rejected", this.result);
        verify(this.response).sendError(expectedStatus);
    }

    private void thenNoSessionIsCreated() {
        verify(this.request, never()).getSession();
        verify(this.request, never()).getSession(true);
        assertNull("no last activity should have been recorded",
                this.session.getAttribute(Attributes.LAST_ACTIVITY.getValue()));
    }

    private void thenSessionIsCreated() {
        verify(this.request, atLeastOnce()).getSession();
        assertNotNull("the created session should record the last activity timestamp",
                this.session.getAttribute(Attributes.LAST_ACTIVITY.getValue()));
        assertNull("the created session must not be authenticated",
                this.session.getAttribute(Attributes.AUTORIZED_USER.getValue()));
        assertNotNull("the created session should be tracked as unauthenticated",
                this.session.getAttribute(Attributes.UNAUTHENTICATED_SESSION.getValue()));
    }
}
